    "id": "tpl-crime-recall-nbw-proclamation",
    "category": "crime",
    "categoryLabel": "Crime",
    "statute": "Bharatiya Nagarik Suraksha Sanhita, 2023 (Sections 72 & 84)",
    "title": "Application for Recall of Non-Bailable Warrant / Discharge of Proclamation (Section 84 BNSS)",
    "shortDesc": "Application for cancellation or recall of non-bailable warrant and dropping of proclamation proceedings under Section 84 BNSS showing absence was bona fide.",
    "limitationNotice": "Bona Fide Absence: Accused must demonstrate absence was non-deliberate due to illness, non-service, or counsel miscommunication.",
